<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store');
$action = $_GET['action'] ?? '';
function body(): array { $data=json_decode(file_get_contents('php://input') ?: '{}',true); return is_array($data)?$data:[]; }
function out(array $data,int $status=200): never { http_response_code($status); echo json_encode($data,JSON_UNESCAPED_UNICODE); exit; }
function user(): array { if(empty($_SESSION['user_id'])) out(['error'=>'Sessão expirada.'],401); global $pdo; $s=$pdo->prepare('SELECT id,name,email,role,timezone FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$u=$s->fetch();if(!$u)out(['error'=>'Usuário não encontrado.'],401);return $u; }
function admin(): array { $u=user(); if($u['role']!=='admin')out(['error'=>'Acesso restrito ao administrador.'],403);return $u; }
function medication(int $id,int $uid): array { global $pdo; $s=$pdo->prepare('SELECT * FROM medications WHERE id=? AND user_id=?');$s->execute([$id,$uid]);$m=$s->fetch();if(!$m)out(['error'=>'Medicamento não encontrado.'],404);return $m; }
function csrf_check(): void { if(in_array($_SERVER['REQUEST_METHOD'],['POST','PUT','PATCH','DELETE'],true) && !hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??'')) out(['error'=>'Token de segurança inválido. Recarregue a página.'],419); }
try {
  $method=$_SERVER['REQUEST_METHOD'];
  csrf_check();
  if($action==='auth.me') out(!empty($_SESSION['user_id'])?user():['id'=>null]);
  if($action==='auth.register'&&$method==='POST'){ $d=body();$name=trim((string)($d['name']??''));$email=strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)out(['error'=>'Informe nome, e-mail válido e senha com pelo menos 8 caracteres.'],422);try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO notification_preferences(user_id) VALUES(?)')->execute([$_SESSION['user_id']]);out(user(),201);}catch(PDOException $e){out(['error'=>$e->getCode()==='23000'?'Este e-mail já está cadastrado.':'Não foi possível criar a conta.'],422);} }
  if($action==='auth.login'&&$method==='POST'){ $d=body();$s=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->execute([strtolower(trim((string)($d['email']??'')))]);$u=$s->fetch();if(!$u||!password_verify((string)($d['password']??''),$u['password_hash']))out(['error'=>'E-mail ou senha incorretos.'],422);session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];out(user()); }
  if($action==='auth.logout'&&$method==='POST'){$_SESSION=[];session_destroy();out(['ok'=>true]);}
  $u=user();$uid=(int)$u['id'];
  if($action==='dashboard'){ $s=$pdo->prepare('SELECT COUNT(*) total_medications,COALESCE(SUM(active=1),0) in_use,COALESCE(SUM(quantity<=minimum_quantity),0) low_stock FROM medications WHERE user_id=?');$s->execute([$uid]);$d=$s->fetch()?:[];$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) month_spending FROM medication_expenses WHERE user_id=? AND spent_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')");$s->execute([$uid]);out(array_merge($d,$s->fetch()?:[])); }
  if($action==='medications'){ $s=$pdo->prepare('SELECT * FROM medications WHERE user_id=? ORDER BY active DESC,name');$s->execute([$uid]);out(['items'=>$s->fetchAll()]); }
  if($action==='medications.create'&&$method==='POST'){ $d=body();if(trim((string)($d['name']??''))==='')out(['error'=>'Informe o nome do medicamento.'],422);$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO medications(user_id,name,active_ingredient,dosage,presentation,quantity,minimum_quantity,expiry_date,frequency,notes) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$uid,trim($d['name']),$d['active_ingredient']??null,$d['dosage']??null,$d['presentation']??'comprimido',(float)($d['quantity']??0),(float)($d['minimum_quantity']??5),$d['expiry_date']??null,$d['frequency']??null,$d['notes']??null]);$mid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO medication_stock(medication_id,quantity,minimum_quantity) VALUES(?,?,?)')->execute([$mid,(float)($d['quantity']??0),(float)($d['minimum_quantity']??5)]);if(!empty($d['schedule_time']))$pdo->prepare('INSERT INTO medication_schedules(medication_id,time_of_day,dose_quantity) VALUES(?,?,?)')->execute([$mid,$d['schedule_time'],(float)($d['dose_quantity']??1)]);if((float)($d['quantity']??0)>0)$pdo->prepare("INSERT INTO stock_movements(medication_id,user_id,type,quantity,reason) VALUES(?,?, 'initial',?, 'Cadastro inicial')")->execute([$mid,$uid,(float)$d['quantity']]);$pdo->commit();out(['id'=>$mid],201); }
  if($action==='medications.update'&&$method==='POST'){ $d=body();$m=medication((int)($d['id']??0),$uid);$s=$pdo->prepare('UPDATE medications SET name=?,active_ingredient=?,dosage=?,presentation=?,quantity=?,minimum_quantity=?,expiry_date=?,frequency=?,notes=? WHERE id=? AND user_id=?');$s->execute([trim($d['name']),$d['active_ingredient']??null,$d['dosage']??null,$d['presentation']??'comprimido',(float)($d['quantity']??0),(float)($d['minimum_quantity']??5),$d['expiry_date']??null,$d['frequency']??null,$d['notes']??null,$m['id'],$uid]);$pdo->prepare('UPDATE medication_stock SET quantity=?,minimum_quantity=? WHERE medication_id=?')->execute([(float)($d['quantity']??0),(float)($d['minimum_quantity']??5),$m['id']]);out(['ok'=>true]); }
  if($action==='schedules'){ $s=$pdo->prepare('SELECT s.*,m.name medication_name,m.unit FROM medication_schedules s JOIN medications m ON m.id=s.medication_id WHERE m.user_id=? AND s.enabled=1 ORDER BY s.time_of_day');$s->execute([$uid]);out(['items'=>$s->fetchAll()]); }
  if($action==='administrations.confirm'&&$method==='POST'){ $d=body();$s=$pdo->prepare('SELECT s.*,m.user_id,m.dose_quantity FROM medication_schedules s JOIN medications m ON m.id=s.medication_id WHERE s.id=? AND m.user_id=?');$s->execute([(int)($d['schedule_id']??0),$uid]);$row=$s->fetch();if(!$row)out(['error'=>'Horário não encontrado.'],404);$pdo->beginTransaction();$pdo->prepare("INSERT INTO medication_administrations(medication_id,user_id,scheduled_for,administered_at,status,dose_quantity) VALUES(?,?,NOW(),NOW(),'administered',?) ON DUPLICATE KEY UPDATE status='administered',administered_at=NOW()")->execute([$row['medication_id'],$uid,(float)$row['dose_quantity']]);$pdo->prepare('UPDATE medications SET quantity=GREATEST(quantity-?,0) WHERE id=? AND user_id=?')->execute([(float)$row['dose_quantity'],$row['medication_id'],$uid]);$pdo->prepare("INSERT INTO stock_movements(medication_id,user_id,type,quantity,reason) VALUES(?,?, 'consumption',?, 'Dose administrada')")->execute([$row['medication_id'],$uid,-(float)$row['dose_quantity']]);$pdo->commit();out(['ok'=>true]); }
  if($action==='purchases'){ $s=$pdo->prepare('SELECT p.*,m.name medication_name,(p.quantity*p.unit_price) total FROM medication_purchases p JOIN medications m ON m.id=p.medication_id WHERE p.user_id=? ORDER BY p.purchased_at DESC');$s->execute([$uid]);out(['items'=>$s->fetchAll()]); }
  if($action==='purchases.create'&&$method==='POST'){ $d=body();$m=medication((int)($d['medication_id']??0),$uid);$qty=(float)($d['quantity']??0);$price=(float)($d['unit_price']??0);if($qty<=0||$price<0)out(['error'=>'Informe quantidade e preço válidos.'],422);$date=$d['purchased_at']??date('Y-m-d');$pdo->beginTransaction();$pdo->prepare('INSERT INTO medication_purchases(medication_id,user_id,purchased_at,quantity,unit_price,pharmacy) VALUES(?,?,?,?,?,?)')->execute([$m['id'],$uid,$date,$qty,$price,$d['pharmacy']??null]);$pid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO medication_expenses(purchase_id,medication_id,user_id,amount,spent_at) VALUES(?,?,?,?,?)')->execute([$pid,$m['id'],$uid,$qty*$price,$date]);$pdo->prepare('UPDATE medications SET quantity=quantity+? WHERE id=?')->execute([$qty,$m['id']]);$pdo->prepare("INSERT INTO stock_movements(medication_id,user_id,type,quantity,reason) VALUES(?,?, 'purchase',?, 'Compra registrada')")->execute([$m['id'],$uid,$qty]);$pdo->commit();out(['id'=>$pid],201); }
  if($action==='push.public-key'){if(!VAPID_PUBLIC_KEY)out(['error'=>'Push ainda não foi configurado no servidor.'],503);out(['public_key'=>VAPID_PUBLIC_KEY]);}
  if($action==='push.subscribe'&&$method==='POST'){ $d=body();if(empty($d['endpoint'])||empty($d['keys']['p256dh'])||empty($d['keys']['auth']))out(['error'=>'Inscrição Push inválida.'],422);$s=$pdo->prepare('INSERT INTO push_subscriptions(user_id,endpoint,p256dh,auth,content_encoding,last_seen_at) VALUES(?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),p256dh=VALUES(p256dh),auth=VALUES(auth),last_seen_at=NOW()');$s->execute([$uid,$d['endpoint'],$d['keys']['p256dh'],$d['keys']['auth'],$d['encoding']??'aes128gcm']);$pdo->prepare('INSERT INTO notification_preferences(user_id,push_enabled) VALUES(?,1) ON DUPLICATE KEY UPDATE push_enabled=1')->execute([$uid]);out(['ok'=>true]); }
  if($action==='admin.notifications.create'&&$method==='POST'){ $a=admin();$d=body();if(trim((string)($d['title']??''))===''||trim((string)($d['body']??''))==='')out(['error'=>'Título e mensagem são obrigatórios.'],422);$when=!empty($d['scheduled_at'])?date('Y-m-d H:i:s',strtotime($d['scheduled_at'])):date('Y-m-d H:i:s');$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO notifications(created_by,title,body,category,scheduled_at) VALUES(?,?,?,?,?)');$s->execute([$a['id'],trim($d['title']),trim($d['body']),$d['category']??'announcement',$when]);$nid=(int)$pdo->lastInsertId();$targets=$pdo->query('SELECT id FROM users')->fetchAll(PDO::FETCH_COLUMN);$rec=$pdo->prepare('INSERT INTO notification_recipients(notification_id,user_id) VALUES(?,?)');$queue=$pdo->prepare('INSERT INTO notification_queue(notification_id,user_id,kind,payload,available_at) VALUES(?,?,?,?,?)');foreach($targets as $target){$rec->execute([$nid,$target]);$queue->execute([$nid,$target,'admin',json_encode(['title'=>$d['title'],'body'=>$d['body'],'url'=>$d['url']??'./']),$when]);}$pdo->commit();out(['id'=>$nid,'recipients'=>count($targets)],201); }
  if($action==='admin.vapid-status'){ admin(); out(['configured'=>VAPID_PUBLIC_KEY!==''&&VAPID_PRIVATE_KEY!=='']); }
  out(['error'=>'Ação não encontrada.'],404);
} catch(Throwable $e) { error_log($e->getMessage()); out(['error'=>'Erro interno. Verifique a configuração do servidor.'],500); }
